# ---------------------------------------------------------------------------
# Traits
# ---------------------------------------------------------------------------


class Trait(Enum):
    """Operation traits that passes and the verifier query."""

    TERMINATOR = auto()
    PURE = auto()
    CONSTANT_LIKE = auto()
    COMMUTATIVE = auto()
    IDEMPOTENT = auto()
    INVOLUTION = auto()
    SAME_OPERANDS_AND_RESULT_TYPE = auto()
    ISOLATED_FROM_ABOVE = auto()
    SYMBOL = auto()
    SYMBOL_TABLE = auto()
    SINGLE_BLOCK = auto()
    NO_TERMINATOR = auto()
    RETURN_LIKE = auto()
    HAS_CLOCK = auto()
    #: The region is an unordered graph region (hardware IR), so a value may be
    #: used textually before the operation that defines it.
    GRAPH_REGION = auto()


# ---------------------------------------------------------------------------
# Types
# ---------------------------------------------------------------------------


class Type(ABC):
    """Base class for all MLIR types.  Types are immutable value objects."""

    @abstractmethod
    def __str__(self) -> str:
        ...

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Type):
            return NotImplemented
        # Types are compared structurally by their textual form, so a dialect
        # refinement such as ``circt.hw.IntType(4)`` equals ``IntegerType(4)``.
        return str(self) == str(other)

    def __ne__(self, other: object) -> bool:
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self) -> int:
        return hash(str(self))

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"{type(self).__name__}({str(self)!r})"

    # -- convenience predicates ------------------------------------------
    @property
    def is_integer(self) -> bool:
        return isinstance(self, IntegerType)

    @property
    def is_signless_integer(self) -> bool:
        return isinstance(self, IntegerType) and self.signedness == "signless"

    def bitwidth(self) -> Optional[int]:
        return None


class IntegerType(Type):
    """``iN``, ``siN`` or ``uiN``."""

    __slots__ = ("width", "signedness")

    def __init__(self, width: int, signedness: str = "signless") -> None:
        if width < 0:
            raise ValueError(f"integer width must be non-negative, got {width}")
        if signedness not in ("signless", "signed", "unsigned"):
            raise ValueError(f"invalid signedness {signedness!r}")
        self.width = int(width)
        self.signedness = signedness

    def __str__(self) -> str:
        prefix = {"signless": "i", "signed": "si", "unsigned": "ui"}[self.signedness]
        return f"{prefix}{self.width}"

    def bitwidth(self) -> Optional[int]:
        return self.width

    @property
    def is_signed(self) -> bool:
        return self.signedness == "signed"

    def mask(self) -> int:
        return (1 << self.width) - 1 if self.width > 0 else 0

    @staticmethod
    def get(width: int, signedness: str = "signless") -> "IntegerType":
        ctx = get_default_context()
        prefix = {"signless": "i", "signed": "si", "unsigned": "ui"}[signedness]
        key = f"{prefix}{width}"
        return ctx.get_or_create_type(key, lambda: IntegerType(width, signedness))  # type: ignore[return-value]


class FloatType(Type):
    """``f16`` / ``f32`` / ``f64`` / ``bf16``."""

    __slots__ = ("width", "mnemonic")

    def __init__(self, width: int, mnemonic: Optional[str] = None) -> None:
        self.width = int(width)
        self.mnemonic = mnemonic or f"f{width}"

    def __str__(self) -> str:
        return self.mnemonic

    def bitwidth(self) -> Optional[int]:
        return self.width


class IndexType(Type):
    """The ``index`` type."""

    def __str__(self) -> str:
        return "index"


class NoneType_(Type):
    """The ``none`` type (spelled ``NoneType_`` to avoid clashing with builtins)."""

    def __str__(self) -> str:
        return "none"


class FunctionType(Type):
    """``(i32, i32) -> i32``."""

    __slots__ = ("inputs", "results")

    def __init__(self, inputs: Sequence[Type], results: Sequence[Type]) -> None:
        self.inputs: Tuple[Type, ...] = tuple(inputs)
        self.results: Tuple[Type, ...] = tuple(results)

    def __str__(self) -> str:
        ins = ", ".join(str(t) for t in self.inputs)
        if len(self.results) == 1:
            outs = str(self.results[0])
        else:
            outs = "(" + ", ".join(str(t) for t in self.results) + ")"
        return f"({ins}) -> {outs}"

    @property
    def num_inputs(self) -> int:
        return len(self.inputs)

    @property
    def num_results(self) -> int:
        return len(self.results)


class TupleType(Type):
    """``tuple<i32, i32>``."""

    __slots__ = ("element_types",)

    def __init__(self, element_types: Sequence[Type]) -> None:
        self.element_types: Tuple[Type, ...] = tuple(element_types)

    def __str__(self) -> str:
        return "tuple<" + ", ".join(str(t) for t in self.element_types) + ">"


class OpaqueType(Type):
    """A dialect type this core layer does not model, e.g. ``!seq.clock``."""

    __slots__ = ("dialect", "mnemonic", "data")

    def __init__(self, dialect: str, mnemonic: str, data: str = "") -> None:
        self.dialect = dialect
        self.mnemonic = mnemonic
        self.data = data

    def __str__(self) -> str:
        body = f"{self.dialect}.{self.mnemonic}"
        if self.data:
            body += f"<{self.data}>"
        return f"!{body}"


# ---------------------------------------------------------------------------
# Attributes
# ---------------------------------------------------------------------------


class Attribute(ABC):
    """Base class for all MLIR attributes."""

    @abstractmethod
    def __str__(self) -> str:
        ...

    @property
    def value(self) -> Any:
        return None

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Attribute):
            return NotImplemented
        return type(self) is type(other) and str(self) == str(other)

class Attribute(ABC):
    """Base class for all MLIR attributes."""

    @abstractmethod
    def __str__(self) -> str:
        ...

    @property
    def value(self) -> Any:
        return None

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Attribute):
            return NotImplemented
        return type(self) is type(other) and str(self) == str(other)

    def __ne__(self, other: object) -> bool:
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self) -> int:
        return hash((type(self).__name__, str(self)))

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"{type(self).__name__}({str(self)!r})"


class UnitAttr(Attribute):
    def __str__(self) -> str:
        return "unit"

    @property
    def value(self) -> Any:
        return True


class BoolAttr(Attribute):
    __slots__ = ("_value",)

    def __init__(self, value: bool) -> None:
        self._value = bool(value)

    def __str__(self) -> str:
        return "true" if self._value else "false"

    @property
    def value(self) -> bool:
        return self._value


class IntegerAttr(Attribute):
    __slots__ = ("_value", "type")

    def __init__(self, value: int, type: Optional[Type] = None) -> None:
        self._value = int(value)
        self.type = type

    def __str__(self) -> str:
        if self.type is None:
            return str(self._value)
        return f"{self._value} : {self.type}"

    @property
    def value(self) -> int:
        return self._value


class FloatAttr(Attribute):
    __slots__ = ("_value", "type")

    def __init__(self, value: float, type: Optional[Type] = None) -> None:
        self._value = float(value)
        self.type = type

    def __str__(self) -> str:
        if self.type is None:
            return repr(self._value)
        return f"{self._value} : {self.type}"

    @property
    def value(self) -> float:
        return self._value


class StringAttr(Attribute):
    __slots__ = ("_value",)

    def __init__(self, value: str) -> None:
        self._value = str(value)

    def __str__(self) -> str:
        escaped = self._value.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{escaped}"'

    @property
    def value(self) -> str:
        return self._value


class TypeAttr(Attribute):
    __slots__ = ("_type",)

    def __init__(self, type: Type) -> None:
        self._type = type

    def __str__(self) -> str:
        return str(self._type)

    @property
    def value(self) -> Type:
        return self._type


class ArrayAttr(Attribute):
    __slots__ = ("_elements",)

    def __init__(self, elements: Sequence[Attribute]) -> None:
        self._elements: Tuple[Attribute, ...] = tuple(elements)

    def __str__(self) -> str:
        return "[" + ", ".join(str(e) for e in self._elements) + "]"

    @property
    def value(self) -> Tuple[Attribute, ...]:
        return self._elements

    def __len__(self) -> int:
        return len(self._elements)

    def __iter__(self) -> Iterator[Attribute]:
        return iter(self._elements)


class DictAttr(Attribute):
    __slots__ = ("_entries",)

    def __init__(self, entries: Optional[Dict[str, Attribute]] = None) -> None:
        self._entries: Dict[str, Attribute] = dict(entries or {})

    def __str__(self) -> str:
        inner = ", ".join(f"{k} = {v}" for k, v in self._entries.items())
        return "{" + inner + "}"

    @property
    def value(self) -> Dict[str, Attribute]:
        return dict(self._entries)

    def __getitem__(self, key: str) -> Attribute:
        return self._entries[key]

    def get(self, key: str, default: Any = None) -> Any:
        return self._entries.get(key, default)


class FlatSymbolRefAttr(Attribute):
    """``@symbol``."""

    __slots__ = ("_symbol",)

    def __init__(self, symbol: str) -> None:
        self._symbol = symbol.lstrip("@")

    def __str__(self) -> str:
        return f"@{self._symbol}"

    @property
    def value(self) -> str:
        return self._symbol


# ---------------------------------------------------------------------------
# Values and uses
# ---------------------------------------------------------------------------


class OpOperand:
    """A single use edge: ``owner``'s operand ``index`` refers to ``value``."""

    __slots__ = ("owner", "index", "value")

    def __init__(self, owner: "Operation", index: int, value: "Value") -> None:
        self.owner = owner
        self.index = index
        self.value = value

    def set(self, value: "Value") -> None:
        if self.value is value:
            return
        self.value.remove_use(self)
        self.value = value
        value.add_use(self)

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"OpOperand({self.owner.name}#{self.index})"


class Value(ABC):
    """An SSA value: either an :class:`OpResult` or a :class:`BlockArgument`."""

    def __init__(self, type: Type, name: Optional[str] = None) -> None:
        self.type = type
        self.name = name
        self._uses: List[OpOperand] = []

# ---------------------------------------------------------------------------
# Symbol tables
# ---------------------------------------------------------------------------


class SymbolTable:
    """Maps ``sym_name`` attributes of the direct children of an op to ops."""

    SYMBOL_ATTR = "sym_name"

    def __init__(self, op: Operation) -> None:
        self.op = op
        self._symbols: Dict[str, Operation] = {}
        for region in op.regions:
            for block in region.blocks:
                for child in block.operations:
                    name = SymbolTable.get_symbol_name(child)
                    if name is not None:
                        self._symbols[name] = child

    @staticmethod
    def get_symbol_name(op: Operation) -> Optional[str]:
        attr = op.attributes.get(SymbolTable.SYMBOL_ATTR)
        if attr is None:
            return None
        return attr.value

    def lookup(self, name: str) -> Optional[Operation]:
        return self._symbols.get(name.lstrip("@"))

    def insert(self, op: Operation) -> None:
        name = SymbolTable.get_symbol_name(op)
        if name is not None:
            self._symbols[name] = op

    @property
    def symbols(self) -> Dict[str, Operation]:
        return dict(self._symbols)

    def names(self) -> List[str]:
        return list(self._symbols)

    def __len__(self) -> int:
        return len(self._symbols)

    def __contains__(self, name: str) -> bool:
        return name.lstrip("@") in self._symbols

    def __iter__(self) -> Iterator[str]:
        return iter(self._symbols)


# ---------------------------------------------------------------------------
# Builders
# ---------------------------------------------------------------------------


class InsertionPoint:
    """Where a builder inserts newly created operations."""

    def __init__(self, block: Block, index: Optional[int] = None) -> None:
        self.block = block
        self.index = index

    @staticmethod
    def at_block_begin(block: Block) -> "InsertionPoint":
        return InsertionPoint(block, 0)

    @staticmethod
    def at_block_end(block: Block) -> "InsertionPoint":
        return InsertionPoint(block, None)

    @staticmethod
    def before(op: Operation) -> "InsertionPoint":
        if op.parent is None:
            raise ValueError("operation has no parent block")
        return InsertionPoint(op.parent, op.parent.operations.index(op))

    @staticmethod
    def after(op: Operation) -> "InsertionPoint":
        if op.parent is None:
            raise ValueError("operation has no parent block")
        return InsertionPoint(op.parent, op.parent.operations.index(op) + 1)

    def insert(self, op: Operation) -> Operation:
        if self.index is None:
            return self.block.append(op)
        inserted = self.block.insert(self.index, op)
        self.index += 1
        return inserted


class OpBuilder:
    """Creates operations at a tracked insertion point."""

    def __init__(self, insertion_point: Optional[InsertionPoint] = None) -> None:
        self.insertion_point = insertion_point

    def set_insertion_point(self, point: InsertionPoint) -> None:
        self.insertion_point = point

    def set_insertion_point_to_end(self, block: Block) -> None:
        self.insertion_point = InsertionPoint.at_block_end(block)

